# Termografias fase 1: revision automatica del Word. Uso: python3 install7.py
import os,subprocess,sys,base64,json
API='/var/www/vibkaptur/public/api'; SCR='/var/www/vibkaptur/scripts'
for n in ('t_7c4n9p2x6d.txt','t_5m8w2r6k1v.txt','t_8f3k2q9x7m.txt'):
    try: os.remove('/var/www/vibkaptur/public/'+n)
    except Exception: pass
P=base64.b64decode(''); H=base64.b64decode('')
open('/tmp/_termo.py','wb').write(P); open('/tmp/_termo.php','wb').write(H)
if subprocess.run(['python3','-m','py_compile','/tmp/_termo.py'],capture_output=True).returncode!=0 or subprocess.run(['php','-l','/tmp/_termo.php'],capture_output=True).returncode!=0:
    print('FALLO de sintaxis. NO SE HA TOCADO NADA'); sys.exit(1)
def put(path,data,ref):
    open(path,'wb').write(data); st=os.stat(ref); os.chown(path,st.st_uid,st.st_gid); os.chmod(path,st.st_mode&0o7777)
put(os.path.join(SCR,'vibk_termo_srv.py'),P,os.path.join(SCR,'vibk_publish_srv.py'))
put(os.path.join(API,'termo.php'),H,os.path.join(API,'revisar.php'))
print('TERMOGRAFIAS: REVISION INSTALADA')
